import { writable, get } from "svelte/store";
import { api, type Task, type Category, type Status } from "../services/api";

export const tasks = writable<Task[]>([]);
export const categories = writable<Category[]>([]);
export const loading = writable(true);
export const undoMessage = writable<string | null>(null);
let undoAction: (() => Promise<void>) | null = null;

export async function undo() {
  const action = undoAction;
  undoAction = null;
  undoMessage.set(null);
  if (action) await action();
}

export async function refresh() {
  loading.set(true);
  try {
    const [t, c] = await Promise.all([api.listTasks({}), api.listCategories()]);
    tasks.set(t);
    categories.set(c);
  } finally {
    loading.set(false);
  }
}

export async function addTask(title: string, categoryId: string | null) {
  const task = await api.createTask({ title, category_id: categoryId });
  tasks.update((all) => [...all, task]);
  return task;
}

export async function toggleStatus(id: string) {
  const current = get(tasks).find((t) => t.id === id);
  if (!current) return;
  const next: Status = current.status === "completed" ? "pending" : "completed";
  const updated = await api.setTaskStatus(id, next);
  if (updated) {
    tasks.update((all) => all.map((t) => (t.id === id ? updated : t)));
    undoAction = async () => {
      const restored = await api.setTaskStatus(id, current.status);
      if (restored) tasks.update((all) => all.map((t) => (t.id === id ? restored : t)));
    };
    undoMessage.set(next === "completed" ? "Task completed" : "Task reopened");
  }
}

export async function removeTask(id: string) {
  const removed = get(tasks).find((t) => t.id === id);
  if (!removed) return;
  await api.deleteTask(id);
  tasks.update((all) => all.filter((t) => t.id !== id));
  undoAction = async () => {
    const restored = await api.createTask(removed);
    tasks.update((all) => [...all, restored]);
  };
  undoMessage.set("Task deleted");
}

export async function updateTask(id: string, patch: Partial<Task>) {
  const previous = get(tasks).find((t) => t.id === id);
  const updated = await api.updateTask(id, patch);
  if (updated) {
    tasks.update((all) => all.map((t) => (t.id === id ? updated : t)));
    if (previous) {
      undoAction = async () => {
        const restored = await api.updateTask(id, previous);
        if (restored) tasks.update((all) => all.map((t) => (t.id === id ? restored : t)));
      };
      undoMessage.set("Task updated");
    }
  }
  return updated;
}

use crate::db::Pool;
use anyhow::{Context, Result};
use rusqlite::{params, OptionalExtension, Row};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
pub enum Status {
    Pending,
    Completed,
    Archived,
}

impl Status {
    fn as_str(&self) -> &'static str {
        match self {
            Status::Pending => "pending",
            Status::Completed => "completed",
            Status::Archived => "archived",
        }
    }
    fn from_str(s: &str) -> Self {
        match s {
            "completed" => Status::Completed,
            "archived" => Status::Archived,
            _ => Status::Pending,
        }
    }
}

// Criticality is a semantic value, not a color (design doc section 7):
// the frontend/theme decides presentation.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, PartialOrd, Ord)]
#[serde(rename_all = "lowercase")]
pub enum Criticality {
    Low,
    Normal,
    High,
    Critical,
}

impl Criticality {
    fn as_str(&self) -> &'static str {
        match self {
            Criticality::Low => "low",
            Criticality::Normal => "normal",
            Criticality::High => "high",
            Criticality::Critical => "critical",
        }
    }
    fn from_str(s: &str) -> Self {
        match s {
            "low" => Criticality::Low,
            "high" => Criticality::High,
            "critical" => Criticality::Critical,
            _ => Criticality::Normal,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Task {
    pub id: String,
    pub title: String,
    pub description: Option<String>,
    pub category_id: Option<String>,
    pub status: Status,
    pub criticality: Criticality,
    pub created_at: String,
    pub updated_at: String,
    pub due_at: Option<String>,
    pub completed_at: Option<String>,
    pub estimated_minutes: Option<i64>,
    pub workspace_id: Option<i64>,
    pub sort_order: i64,
    pub parent_id: Option<String>,
}

#[derive(Debug, Deserialize)]
pub struct NewTask {
    pub title: String,
    pub description: Option<String>,
    pub category_id: Option<String>,
    pub criticality: Option<Criticality>,
    pub due_at: Option<String>,
    pub estimated_minutes: Option<i64>,
    pub parent_id: Option<String>,
    pub workspace_id: Option<i64>,
}

#[derive(Debug, Default, Deserialize)]
pub struct TaskFilter {
    pub category_id: Option<String>,
    pub status: Option<Status>,
    pub criticality: Option<Criticality>,
}

fn row_to_task(row: &Row) -> rusqlite::Result<Task> {
    Ok(Task {
        id: row.get("id")?,
        title: row.get("title")?,
        description: row.get("description")?,
        category_id: row.get("category_id")?,
        status: Status::from_str(&row.get::<_, String>("status")?),
        criticality: Criticality::from_str(&row.get::<_, String>("criticality")?),
        created_at: row.get("created_at")?,
        updated_at: row.get("updated_at")?,
        due_at: row.get("due_at")?,
        completed_at: row.get("completed_at")?,
        estimated_minutes: row.get("estimated_minutes")?,
        workspace_id: row.get("workspace_id")?,
        sort_order: row.get("sort_order")?,
        parent_id: row.get("parent_id")?,
    })
}

const SELECT_COLS: &str = "id, title, description, category_id, status, criticality, \
     created_at, updated_at, due_at, completed_at, estimated_minutes, \
     workspace_id, sort_order, parent_id";

pub fn create(pool: &Pool, new: NewTask) -> Result<Task> {
    let conn = pool.get()?;
    let id = Uuid::new_v4().to_string();
    let criticality = new.criticality.unwrap_or(Criticality::Normal);
    conn.execute(
        "INSERT INTO tasks (id, title, description, category_id, criticality, due_at, \
         estimated_minutes, parent_id, workspace_id) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9)",
        params![
            id,
            new.title,
            new.description,
            new.category_id,
            criticality.as_str(),
            new.due_at,
            new.estimated_minutes,
            new.parent_id,
            new.workspace_id,
        ],
    )
    .context("inserting task")?;
    get(pool, &id)?.context("task disappeared immediately after insert")
}

pub fn get(pool: &Pool, id: &str) -> Result<Option<Task>> {
    let conn = pool.get()?;
    let task = conn
        .query_row(
            &format!("SELECT {SELECT_COLS} FROM tasks WHERE id = ?1"),
            params![id],
            row_to_task,
        )
        .optional()
        .context("querying task by id")?;
    Ok(task)
}

pub fn list(pool: &Pool, filter: &TaskFilter) -> Result<Vec<Task>> {
    let conn = pool.get()?;
    let mut sql = format!("SELECT {SELECT_COLS} FROM tasks WHERE 1=1");
    let mut binds: Vec<Box<dyn rusqlite::ToSql>> = Vec::new();

    if let Some(cat) = &filter.category_id {
        sql.push_str(" AND category_id = ?");
        binds.push(Box::new(cat.clone()));
    }
    if let Some(status) = &filter.status {
        sql.push_str(" AND status = ?");
        binds.push(Box::new(status.as_str().to_string()));
    }
    if let Some(crit) = &filter.criticality {
        sql.push_str(" AND criticality = ?");
        binds.push(Box::new(crit.as_str().to_string()));
    }
    sql.push_str(" ORDER BY sort_order ASC, created_at ASC");

    let mut stmt = conn.prepare(&sql).context("preparing task list query")?;
    let params_refs: Vec<&dyn rusqlite::ToSql> = binds.iter().map(|b| b.as_ref()).collect();
    let rows = stmt
        .query_map(params_refs.as_slice(), row_to_task)
        .context("executing task list query")?;

    let mut out = Vec::new();
    for r in rows {
        out.push(r?);
    }
    Ok(out)
}

#[derive(Debug, Default, Deserialize)]
pub struct TaskUpdate {
    pub title: Option<String>,
    pub description: Option<String>,
    pub category_id: Option<String>,
    pub criticality: Option<Criticality>,
    pub due_at: Option<String>,
    pub estimated_minutes: Option<i64>,
    pub sort_order: Option<i64>,
}

pub fn update(pool: &Pool, id: &str, patch: TaskUpdate) -> Result<Option<Task>> {
    let conn = pool.get()?;
    conn.execute(
        "UPDATE tasks SET
            title              = COALESCE(?2, title),
            description        = COALESCE(?3, description),
            category_id        = COALESCE(?4, category_id),
            criticality        = COALESCE(?5, criticality),
            due_at             = COALESCE(?6, due_at),
            estimated_minutes  = COALESCE(?7, estimated_minutes),
            sort_order         = COALESCE(?8, sort_order),
            updated_at         = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
         WHERE id = ?1",
        params![
            id,
            patch.title,
            patch.description,
            patch.category_id,
            patch.criticality.map(|c| c.as_str().to_string()),
            patch.due_at,
            patch.estimated_minutes,
            patch.sort_order,
        ],
    )
    .context("updating task")?;
    drop(conn);
    get(pool, id)
}

/// Toggles between pending and completed. This is the `Space` / `c` action
/// from the keyboard system (design doc section 19) and drives the
/// completed_at timestamp used for "done" filtering.
pub fn set_status(pool: &Pool, id: &str, status: Status) -> Result<Option<Task>> {
    let conn = pool.get()?;
    let completed_at = matches!(status, Status::Completed).then(|| chrono_now());
    conn.execute(
        "UPDATE tasks SET status = ?2, completed_at = ?3,
            updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
         WHERE id = ?1",
        params![id, status.as_str(), completed_at],
    )
    .context("updating task status")?;
    drop(conn);
    get(pool, id)
}

pub fn delete(pool: &Pool, id: &str) -> Result<()> {
    let conn = pool.get()?;
    conn.execute("DELETE FROM tasks WHERE id = ?1", params![id])
        .context("deleting task")?;
    Ok(())
}

/// Summary counts used by the Waybar module (design doc section 15) and the
/// dashboard header. Kept as a single cheap query rather than three round
/// trips, per the "minimize database queries" principle (section 2.2).
#[derive(Debug, Serialize)]
pub struct TaskCounts {
    pub pending: i64,
    pub critical_pending: i64,
    pub overdue: i64,
}

pub fn counts(pool: &Pool) -> Result<TaskCounts> {
    let conn = pool.get()?;
    let mut stmt = conn.prepare(
        "SELECT
            SUM(CASE WHEN status = 'pending' THEN 1 ELSE 0 END),
            SUM(CASE WHEN status = 'pending' AND criticality = 'critical' THEN 1 ELSE 0 END),
            SUM(CASE WHEN status = 'pending' AND due_at IS NOT NULL
                     AND due_at < strftime('%Y-%m-%dT%H:%M:%fZ', 'now') THEN 1 ELSE 0 END)
         FROM tasks",
    )?;
    let (pending, critical_pending, overdue): (Option<i64>, Option<i64>, Option<i64>) =
        stmt.query_row([], |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)))?;
    Ok(TaskCounts {
        pending: pending.unwrap_or(0),
        critical_pending: critical_pending.unwrap_or(0),
        overdue: overdue.unwrap_or(0),
    })
}

/// Matches SQLite's `strftime('%Y-%m-%dT%H:%M:%fZ', 'now')` format exactly
/// (millisecond precision, trailing `Z`) so `completed_at` sorts and
/// compares correctly against `created_at`/`updated_at`/`due_at`, all of
/// which are stamped by SQLite itself rather than by this Rust code.
fn chrono_now() -> String {
    chrono::Utc::now().format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string()
}

// `hyprtodo-cli` — the headless entry point from design doc Milestone 2.
// Talks to the same SQLite database as the GUI, so `hyprtodo-cli add` and
// the Tauri window stay in sync without any IPC between them.

use clap::{Parser, Subcommand};
use hyprtodo::db;
use hyprtodo::tasks::{self, Criticality, NewTask, Status, TaskFilter};

#[derive(Parser)]
#[command(name = "hyprtodo", about = "Fast, keyboard-first task manager for Hyprland")]
struct Cli {
    #[command(subcommand)]
    command: Command,
}

#[derive(Subcommand)]
enum Command {
    /// Add a new task
    Add {
        title: Vec<String>,
        #[arg(short, long)]
        category: Option<String>,
        #[arg(short = 'C', long, value_enum)]
        criticality: Option<CriticalityArg>,
        #[arg(short, long)]
        due: Option<String>,
    },
    /// List tasks
    List {
        #[arg(short, long)]
        category: Option<String>,
        /// Include completed tasks
        #[arg(short, long)]
        all: bool,
    },
    /// Mark a task complete by id (or id prefix)
    Done { id: String },
    /// Print pending, critical, and overdue counts as JSON
    Counts { #[arg(long)] json: bool },
}

#[derive(Clone, clap::ValueEnum)]
enum CriticalityArg {
    Low,
    Normal,
    High,
    Critical,
}

impl From<CriticalityArg> for Criticality {
    fn from(v: CriticalityArg) -> Self {
        match v {
            CriticalityArg::Low => Criticality::Low,
            CriticalityArg::Normal => Criticality::Normal,
            CriticalityArg::High => Criticality::High,
            CriticalityArg::Critical => Criticality::Critical,
        }
    }
}

fn main() -> anyhow::Result<()> {
    let cli = Cli::parse();
    let pool = db::init_pool()?;

    match cli.command {
        Command::Add { title, category, criticality, due } => {
            let title = title.join(" ");
            if title.trim().is_empty() {
                anyhow::bail!("task title cannot be empty");
            }
            let task = tasks::create(
                &pool,
                NewTask {
                    title,
                    description: None,
                    category_id: category,
                    criticality: criticality.map(Into::into),
                    due_at: due,
                    estimated_minutes: None,
                    parent_id: None,
                    workspace_id: None,
                },
            )?;
            println!("added [{}] {}", &task.id[..8], task.title);
        }
        Command::List { category, all } => {
            let filter = TaskFilter {
                category_id: category,
                status: if all { None } else { Some(Status::Pending) },
                criticality: None,
            };
            let list = tasks::list(&pool, &filter)?;
            if list.is_empty() {
                println!("no tasks");
            }
            for t in list {
                let marker = match t.status {
                    Status::Completed => "x",
                    Status::Archived => "-",
                    Status::Pending => " ",
                };
                let due = t.due_at.map(|d| format!("  (due {d})")).unwrap_or_default();
                println!("[{}] {} {}{}", marker, &t.id[..8], t.title, due);
            }
        }
        Command::Done { id } => {
            // Resolve a short id prefix to a full task id, mirroring how a
            // person would type the first 8 chars printed by `list`.
            let filter = TaskFilter::default();
            let candidates: Vec<_> = tasks::list(&pool, &filter)?
                .into_iter()
                .filter(|t| t.id.starts_with(&id))
                .collect();
            match candidates.as_slice() {
                [] => anyhow::bail!("no task matches id '{id}'"),
                [only] => {
                    tasks::set_status(&pool, &only.id, Status::Completed)?;
                    println!("completed: {}", only.title);
                }
                _ => anyhow::bail!("id '{id}' is ambiguous, use more characters"),
            }
        }
        Command::Counts { json } => {
            let counts = tasks::counts(&pool)?;
            if json {
                println!("{}", serde_json::to_string(&counts)?);
            } else {
                println!("{} pending, {} critical, {} overdue", counts.pending, counts.critical_pending, counts.overdue);
            }
        }
    }
    Ok(())
}

import { invoke } from "@tauri-apps/api/core";

export type Status = "pending" | "completed" | "archived";
export type Criticality = "low" | "normal" | "high" | "critical";

export interface Task {
  id: string;
  title: string;
  description: string | null;
  category_id: string | null;
  status: Status;
  criticality: Criticality;
  created_at: string;
  updated_at: string;
  due_at: string | null;
  completed_at: string | null;
  estimated_minutes: number | null;
  workspace_id: number | null;
  sort_order: number;
  parent_id: string | null;
}

export interface Category {
  id: string;
  name: string;
  icon: string | null;
  color: string | null;
  sort_order: number;
}

export interface TaskFilter {
  category_id?: string | null;
  status?: Status | null;
  criticality?: Criticality | null;
}

export interface TaskCounts {
  pending: number;
  critical_pending: number;
  overdue: number;
}

// Every function here is a thin, 1:1 mirror of a #[tauri::command] in
// src-tauri/src/commands/mod.rs. Keeping it flat (no client-side caching or
// derived state) means the SQLite database stays the single source of
// truth, per design doc section 47.

export const api = {
  listTasks: (filter: TaskFilter = {}) => invoke<Task[]>("list_tasks", { filter }),

  createTask: (task: {
    title: string;
    description?: string | null;
    category_id?: string | null;
    criticality?: Criticality | null;
    due_at?: string | null;
    estimated_minutes?: number | null;
    parent_id?: string | null;
    workspace_id?: number | null;
  }) => invoke<Task>("create_task", { task }),

  updateTask: (id: string, patch: Partial<Task>) =>
    invoke<Task | null>("update_task", { id, patch }),

  setTaskStatus: (id: string, status: Status) =>
    invoke<Task | null>("set_task_status", { id, status }),

  deleteTask: (id: string) => invoke<void>("delete_task", { id }),

  taskCounts: () => invoke<TaskCounts>("task_counts"),

  listCategories: () => invoke<Category[]>("list_categories"),

  createCategory: (category: { id: string; name: string; icon?: string; color?: string }) =>
    invoke<Category>("create_category", { category }),

  deleteCategory: (id: string) => invoke<void>("delete_category", { id }),

  renameCategory: (id: string, name: string) => invoke<void>("rename_category", { id, name }),

  reorderCategory: (id: string, direction: number) =>
    invoke<void>("reorder_category", { id, direction }),

  getColumns: () => invoke<number>("get_columns"),

  setColumns: (n: number) => invoke<void>("set_columns", { n }),
  getPreferences: () => invoke<Record<string, unknown>>("get_preferences"),
  activeWorkspace: () => invoke<number | null>("active_workspace"),
};

import { writable, get } from "svelte/store";
import { api, type Task, type Category, type Status } from "../services/api";

export const tasks = writable<Task[]>([]);
export const categories = writable<Category[]>([]);
export const loading = writable(true);
export const undoMessage = writable<string | null>(null);
let undoAction: (() => Promise<void>) | null = null;

export async function undo() {
  const action = undoAction;
  undoAction = null;
  undoMessage.set(null);
  if (action) await action();
}

export async function refresh() {
  loading.set(true);
  try {
    const [t, c] = await Promise.all([api.listTasks({}), api.listCategories()]);
    tasks.set(t);
    categories.set(c);
  } finally {
    loading.set(false);
  }
}

export async function addTask(title: string, categoryId: string | null, workspaceId: number | null = null) {
  const task = await api.createTask({ title, category_id: categoryId, workspace_id: workspaceId });
  tasks.update((all) => [...all, task]);
  return task;
}

export async function toggleStatus(id: string) {
  const current = get(tasks).find((t) => t.id === id);
  if (!current) return;
  const next: Status = current.status === "completed" ? "pending" : "completed";
  const updated = await api.setTaskStatus(id, next);
  if (updated) {
    tasks.update((all) => all.map((t) => (t.id === id ? updated : t)));
    undoAction = async () => {
      const restored = await api.setTaskStatus(id, current.status);
      if (restored) tasks.update((all) => all.map((t) => (t.id === id ? restored : t)));
    };
    undoMessage.set(next === "completed" ? "Task completed" : "Task reopened");
  }
}

export async function removeTask(id: string) {
  const removed = get(tasks).find((t) => t.id === id);
  if (!removed) return;
  await api.deleteTask(id);
  tasks.update((all) => all.filter((t) => t.id !== id));
  undoAction = async () => {
    const restored = await api.createTask(removed);
    tasks.update((all) => [...all, restored]);
  };
  undoMessage.set("Task deleted");
}

export async function updateTask(id: string, patch: Partial<Task>) {
  const previous = get(tasks).find((t) => t.id === id);
  const updated = await api.updateTask(id, patch);
  if (updated) {
    tasks.update((all) => all.map((t) => (t.id === id ? updated : t)));
    if (previous) {
      undoAction = async () => {
        const restored = await api.updateTask(id, previous);
        if (restored) tasks.update((all) => all.map((t) => (t.id === id ? restored : t)));
      };
      undoMessage.set("Task updated");
    }
  }
  return updated;
}

