    "linux": {
      "deb": {
        "depends": []
      }
    }
  }
}

/* Safe defaults (design doc 2.6): looks good with zero configuration.
   Milestone 5 will let Lua's theme() call rewrite these variables at
   runtime; until then they're the static built-in theme. */
:root {
  --background: #0d1117;
  --panel-bg: #161b22;
  --foreground: #c9d1d9;
  --muted: #8b949e;
  --accent: #58a6ff;
  --border: #30363d;
  --control-bg: #18212d;
  --control-hover: #253449;
  --control-border: #344b67;
  --control-primary: #245078;

  --crit-low: #8b949e;
  --crit-normal: #c9d1d9;
  --crit-high: #d29922;
  --crit-critical: #f85149;

  --opacity: 0.92;
  --radius: 14px;
  --border-width: 1px;
  --task-gap: 8px;

  --font-ui: "Inter", system-ui, sans-serif;
  --font-heading: "JetBrainsMono Nerd Font", monospace;
  --font-mono: "JetBrainsMono Nerd Font", monospace;
  --font-icon: "Symbols Nerd Font Mono", sans-serif;

  --font-size-ui: 14px;
  --font-size-heading: 16px;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  height: 100%;
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-ui);
  font-size: var(--font-size-ui);
  -webkit-font-smoothing: antialiased;
  user-select: none;
}

#app {
  height: 100vh;
}
